from pathlib import Path
import hashlib,json
ROOT=Path(__file__).resolve().parent
FILES={'dependency_impact': {'contract.json': '{\n  "package": "dependency_impact",\n  "objective": "Normalize a dependency graph, compute shortest downstream impact and strongly connected components, then produce a deterministic report.",\n  "owned_files": [\n    "normalize.py",\n    "engine.py",\n    "report.py",\n    "cli.py"\n  ],\n  "public_api": {\n    "normalize.py": "normalization helpers",\n    "engine.py": "core algorithm",\n    "report.py": "deterministic report",\n    "cli.py": "read input JSON, write output JSON"\n  },\n  "constraints": [\n    "standard library only",\n    "stable ordering",\n    "do not edit contract.json or check_module.py",\n    "python3 check_module.py must pass"\n  ]\n}\n', 'check_module.py': 'import hashlib,json,time\nfrom pathlib import Path\nstarted=time.perf_counter()\nfrom engine import impacted, strongly_connected\nfrom report import build_report\nassert impacted([["a","b"],["b","c"],["c","b"],["x","y"]], ["a"]) == {"a":0,"b":1,"c":2}\nassert ["b","c"] in strongly_connected([["a","b"],["b","c"],["c","b"]])\nedges = [(f"n{i}", f"n{(i*17+31)%12000}") for i in range(12000)] + [(f"n{i}", f"n{(i+1)%12000}") for i in range(12000)]\nfor r in range(240):\n    out = build_report(edges, [f"n{(r*97)%12000}"])\n    assert len(out["checksum"]) == 64 and out["distances"]\nelapsed=time.perf_counter()-started\nowned=[\'normalize.py\',\'engine.py\',\'report.py\',\'cli.py\']\nhashes={p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in owned}\nPath(\'.focused-pass.json\').write_text(json.dumps({\'package\':\'dependency_impact\',\'passed\':True,\'implementation_hashes\':hashes,\'elapsed_seconds\':elapsed},sort_keys=True,indent=2)+\'\\n\')\nprint(\'FOCUSED_CHECK_PASS\',\'dependency_impact\',round(elapsed,3))\n', 'normalize.py': "raise NotImplementedError('implement normalize.py')\n", 'engine.py': "raise NotImplementedError('implement engine.py')\n", 'report.py': "raise NotImplementedError('implement report.py')\n", 'cli.py': 'import argparse, json\nfrom pathlib import Path\nfrom report import build_report\n\ndef main():\n    p=argparse.ArgumentParser(); p.add_argument("input"); p.add_argument("output"); a=p.parse_args()\n    data=json.loads(Path(a.input).read_text()); out=build_report(data[\'edges\'], data[\'seeds\'])\n    Path(a.output).parent.mkdir(parents=True,exist_ok=True); Path(a.output).write_text(json.dumps(out,sort_keys=True,indent=2)+"\\n")\nif __name__ == "__main__": main()\n'}, 'policy_precedence': {'contract.json': '{\n  "package": "policy_precedence",\n  "objective": "Evaluate wildcard policy rules using priority, specificity, deny tie-break and stable identifiers, with an explainable deterministic report.",\n  "owned_files": [\n    "normalize.py",\n    "engine.py",\n    "report.py",\n    "cli.py"\n  ],\n  "public_api": {\n    "normalize.py": "normalization helpers",\n    "engine.py": "core algorithm",\n    "report.py": "deterministic report",\n    "cli.py": "read input JSON, write output JSON"\n  },\n  "constraints": [\n    "standard library only",\n    "stable ordering",\n    "do not edit contract.json or check_module.py",\n    "python3 check_module.py must pass"\n  ]\n}\n', 'check_module.py': 'import hashlib,json,time\nfrom pathlib import Path\nstarted=time.perf_counter()\nfrom engine import decide\nfrom report import evaluate\nrules=[{"id":"fallback","effect":"allow","priority":1},{"id":"deny-admin","effect":"deny","priority":9,"resource":"admin/*"},{"id":"allow-read","effect":"allow","priority":9,"resource":"admin/report","action":"read"}]\nassert decide(rules,"admin/report","read")["rule_id"] == "allow-read"\nassert decide(rules,"admin/users","write")["effect"] == "deny"\nlarge=[{"id":f"r{i}","effect":"deny" if i%11==0 else "allow","priority":i%17,"resource":f"svc{i%211}*","action":"read" if i%3 else "*"} for i in range(1600)]\nrequests=[{"resource":f"svc{i%211}/object/{i}","action":"read" if i%2 else "write"} for i in range(5000)]\nfor r in range(4):\n    out=evaluate(large,requests); assert out["allow"]+out["deny"] == len(requests) and len(out["checksum"]) == 64\nelapsed=time.perf_counter()-started\nowned=[\'normalize.py\',\'engine.py\',\'report.py\',\'cli.py\']\nhashes={p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in owned}\nPath(\'.focused-pass.json\').write_text(json.dumps({\'package\':\'policy_precedence\',\'passed\':True,\'implementation_hashes\':hashes,\'elapsed_seconds\':elapsed},sort_keys=True,indent=2)+\'\\n\')\nprint(\'FOCUSED_CHECK_PASS\',\'policy_precedence\',round(elapsed,3))\n', 'normalize.py': "raise NotImplementedError('implement normalize.py')\n", 'engine.py': "raise NotImplementedError('implement engine.py')\n", 'report.py': "raise NotImplementedError('implement report.py')\n", 'cli.py': 'import argparse, json\nfrom pathlib import Path\nfrom report import evaluate\n\ndef main():\n    p=argparse.ArgumentParser(); p.add_argument("input"); p.add_argument("output"); a=p.parse_args()\n    data=json.loads(Path(a.input).read_text()); out=evaluate(data[\'rules\'], data[\'requests\'])\n    Path(a.output).parent.mkdir(parents=True,exist_ok=True); Path(a.output).write_text(json.dumps(out,sort_keys=True,indent=2)+"\\n")\nif __name__ == "__main__": main()\n'}, 'event_windows': {'contract.json': '{\n  "package": "event_windows",\n  "objective": "Deduplicate event revisions and compute deterministic keyed tumbling-window aggregates including nearest-rank p95.",\n  "owned_files": [\n    "normalize.py",\n    "engine.py",\n    "report.py",\n    "cli.py"\n  ],\n  "public_api": {\n    "normalize.py": "normalization helpers",\n    "engine.py": "core algorithm",\n    "report.py": "deterministic report",\n    "cli.py": "read input JSON, write output JSON"\n  },\n  "constraints": [\n    "standard library only",\n    "stable ordering",\n    "do not edit contract.json or check_module.py",\n    "python3 check_module.py must pass"\n  ]\n}\n', 'check_module.py': 'import hashlib,json,time\nfrom pathlib import Path\nstarted=time.perf_counter()\nfrom engine import aggregate\nfrom report import window_report\nrows=[{"id":"x","ts":3,"key":"a","value":2},{"id":"y","ts":9,"key":"a","value":4},{"id":"x","ts":4,"key":"a","value":5}]\nassert aggregate(rows,10) == [{"start":0,"end":10,"key":"a","count":2,"sum":9.0,"p95":5.0}]\nevents=[{"id":f"e{i}","ts":i*13%900000,"key":f"k{i%127}","value":float((i*29)%1000)} for i in range(1000000)]\nfor size in (60,120,300,600,900,1800,3600,7200,14400,28800):\n    out=window_report(events,size); assert out["windows"] and len(out["checksum"]) == 64\nelapsed=time.perf_counter()-started\nowned=[\'normalize.py\',\'engine.py\',\'report.py\',\'cli.py\']\nhashes={p:hashlib.sha256(Path(p).read_bytes()).hexdigest() for p in owned}\nPath(\'.focused-pass.json\').write_text(json.dumps({\'package\':\'event_windows\',\'passed\':True,\'implementation_hashes\':hashes,\'elapsed_seconds\':elapsed},sort_keys=True,indent=2)+\'\\n\')\nprint(\'FOCUSED_CHECK_PASS\',\'event_windows\',round(elapsed,3))\n', 'normalize.py': "raise NotImplementedError('implement normalize.py')\n", 'engine.py': "raise NotImplementedError('implement engine.py')\n", 'report.py': "raise NotImplementedError('implement report.py')\n", 'cli.py': 'import argparse, json\nfrom pathlib import Path\nfrom report import window_report\n\ndef main():\n    p=argparse.ArgumentParser(); p.add_argument("input"); p.add_argument("output"); a=p.parse_args()\n    data=json.loads(Path(a.input).read_text()); out=window_report(data[\'events\'], int(data[\'window_size\']))\n    Path(a.output).parent.mkdir(parents=True,exist_ok=True); Path(a.output).write_text(json.dumps(out,sort_keys=True,indent=2)+"\\n")\nif __name__ == "__main__": main()\n'}}
for package, files in FILES.items():
    target=ROOT/'products'/package; target.mkdir(parents=True,exist_ok=True)
    for name,content in files.items(): (target/name).write_text(content,encoding='utf-8')
manifest={'schema':'dynamic-products/v1','products':sorted(FILES),'contracts':{}}
for package in sorted(FILES):
    raw=(ROOT/'products'/package/'contract.json').read_bytes(); manifest['contracts'][package]=hashlib.sha256(raw).hexdigest()
out=ROOT/'outputs'/'shared_manifest.json'; out.parent.mkdir(parents=True,exist_ok=True); out.write_text(json.dumps(manifest,sort_keys=True,indent=2)+'\n')
print('MATERIALIZED',len(FILES),out)
